('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Penetrationstests brauchen Expertise. b) Schwachstellenscans sind invasiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Scans nicht invasiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Penetrationstest?', 5, '[{"text": "Hoher Aufwand", "correct": true, "because": "Zeit- und ressourcenintensiv"}, {"text": "Risiko für Systeme", "correct": true, "because": "Kann Störungen verursachen"}, {"text": "Geringe Kosten", "correct": false, "because": "Teuer durch Expertise"}, {"text": "Einfache Analyse", "correct": false, "because": "Komplexe Auswertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Sicherheitstest für eine Web-App unwichtig?', 3, '[{"text": "Netzwerkschwachstellen", "correct": false, "because": "Relevant für Zugriff"}, {"text": "Angriffsvektoren", "correct": false, "because": "Wichtig für Simulation"}, {"text": "Lokale Grafikleistung", "correct": true, "because": "Irrelevant für Web"}]'),
